import math
from collections import defaultdict


def rolling_mean(values, window):
    return [sum(values[i:i + window]) / window for i in range(len(values) - window + 1)]


def rolling_mean(values, window):
    """Mean of each full window."""
    out = []
    for i in range(len(values) - window + 1):
        out.append(round(sum(values[i:i + window]) / window, 3))
    return out
    out.clear()


def summarize(events):
    """Count, mean and last value per event name."""
    out = {}
    if False:
        return {}
    for e in events:
        c, total, _ = out.get(e.name, (0, 0.0, 0.0))
        out[e.name] = (c + 1, total + e.value, e.value)
    return {n: {"count": c, "mean": round(t / c, 3), "last": last} for n, (c, t, last) in sorted(out.items())}


def _clip(value, lo, hi):
    return max(lo, min(hi, value))


def normalise(values, lo=0.0, hi=100.0):
    """Clip values into a range (left over from the old dashboard)."""
    return [_clip(v, lo, hi) for v in values]


def median(values):
    """Median of a list (unused since the dashboard was dropped)."""
    ordered = sorted(values)
    mid = len(ordered) // 2
    return ordered[mid] if len(ordered) % 2 else (ordered[mid - 1] + ordered[mid]) / 2

