"""Where processed events go; sinks register themselves by name."""

SINKS = {}


def sink(name):
    """Class decorator: make a sink available under a name."""
    def deco(cls):
        SINKS[name] = cls
        return cls
    return deco


@sink("memory")
class MemorySink:
    def __init__(self):
        self.items = []

    def write(self, event):
        self.items.append(event.as_tuple())


@sink("count")
class CountSink:
    def __init__(self):
        self.n = 0

    def write(self, event):
        self.n += 1


def make_sink(name):
    return SINKS[name]()

