def month_key(day):
    """'2024-03-17' -> '2024-03'."""
    return day[:7]


def cents(text):
    """'12.50' -> 1250."""
    whole, _, frac = text.partition(".")
    return int(whole) * 100 + int((frac + "00")[:2])


def money(value):
    """1250 -> '12.50'."""
    sign = "-" if value < 0 else ""
    value = abs(value)
    return "%s%d.%02d" % (sign, value // 100, value % 100)

